    {
      number: 'INV-001',
      customerId: 'C-001',
      status: 'issued',
      dueDate: '2026-10-10',
      lines: [{ sku: 'STICKER', qty: 100, name: 'Sticker sheet', unitPrice: 50, vatRate: 21, discountPercent: 0 }],
      terms: 'NET30',
    },
    {
      number: 'INV-002',
      customerId: 'C-002',
      status: 'issued',
      dueDate: '2026-10-05',
      lines: [{ sku: 'STICKER', qty: 100, name: 'Sticker sheet', unitPrice: 50, vatRate: 21, discountPercent: 0 }],
